            from: 1,
            to: EVIDENCE_VERSION,
        }),
        ArtifactEvidence::Verified(evidence) if evidence.schema_version == 2 => {
            Err(JournalError::MigrationRequired {
                from: 2,
                to: EVIDENCE_VERSION,
