       digest: zero_workflow_digest(),
       source_digest: workflow.digest(),
       policy_digest: compute_policy_digest(workflow)?,
       ir,
       verification: proof,
       accepted_at_seq: EventSeq::new(0),
       required_capabilities: required_capabilities_from_contracts(contracts)?,
       action_contracts: contracts.to_vec().into_boxed_slice(),
   };
   bind_artifact_digest(&mut artifact)?;
   Ok(artifact)
   ```

   The `ir` field is set before the `accepted_at_seq` field. The `ir` field contains the encoded `WorkflowParts`, not the entire `AcceptedArtifact`. So `ir` does not include the seq number.

   Looking at `prepare_artifact` in the artifact_acceptance module:
   ```rust
   fn prepare_artifact(
       last: u64,
       artifact: AcceptedArtifact,
   ) -> Result<(u64, AcceptedArtifact), JournalError> {
       let next = last.checked_add(1).ok_or(JournalError::SequenceOverflow)?;
       let seq = IssuedArtifactSequence::new(next)?;
       let mut stamped = artifact;
       stamped.accepted_at_seq = seq.to_event_seq();
       bind_artifact_digest(&mut stamped)?;
       Ok((next, stamped))
   }
   ```

